def get_max_sum(n):
    # Initialize a dictionary to store computed values for memoization
    memo = {0: 0, 1: 1}

    # Define a helper function to compute the maximum sum using memoization
    def helper(x):
        if x not in memo:
            # Recursively compute the maximum sum using the given equation
            memo[x] = max(helper(x // 2) + helper(x // 3) + helper(x // 4) + helper(x // 5), x)
        return memo[x]

    # Call the helper function with the input n
    return helper(n)

def catalan_number(n):
    # Base case: the first Catalan number is 1
    if n == 0:
        return 1

    # Initialize the result
    result = 0

    # Calculate the nth Catalan number using the formula
    for i in range(n):
        result += catalan_number(i) * catalan_number(n - i - 1)

    return result

def hexagonal_num(n):
