def sumofFactors(n): 
    result = 1
    i = 2
    while i * i <= n: 
        count = 0
        curr_sum = 1
        curr_term = 1
        while n % i == 0: 
            count += 1
            n //= i 
            if count % 2 == 1: 
                curr_sum = curr_sum * i + curr_term 
            else: 
                curr_sum = curr_sum * i - curr_term 
            curr_term = curr_term * i 
        result *= curr_sum 
        i += 1
    if n >= 2: 
        result *= (1 + n) 
    return result - n  # Subtract the number itself if it's greater than 1

def pair_xor_Sum(arr, n):
    # Initialize the result
    result = 0

    # Iterate over each bit position
    for i in range(32):
        # Count the number of elements with the i-th bit set
        count = 0
        for j in range(n):
            if (arr[j] & (1 << i)) != 0:
                count += 1

        # Calculate the contribution of the i-th bit to the result
        result += (1 << i) * count * (n - count)

    return result

