def newman_prime(n):
    # Initialize the list of Newman-Shanks-Williams primes with the first two known primes
    primes = [2, 3]

    # Function to check if a number is prime
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Function to generate the next Newman-Shanks-Williams prime
    def next_newman_prime(prev):
        next_num = prev + sum(primes[-i-1] for i in range(len(primes)))
        while not is_prime(next_num):
            next_num += 1
        return next_num

    # Generate Newman-Shanks-Williams primes until we have the nth one
    while len(primes) < n:
        next_prime = next_newman_prime(primes[-1])
        primes.append(next_prime)

    # Return the nth Newman-Shanks-Williams prime
    return primes[n-1]

