def find_kth(arr1, arr2, k):
    # Initialize pointers for both arrays
    i, j = 0, 0

    # Loop until we find the kth element or exhaust one of the arrays
    while i < len(arr1) and j < len(arr2) and k > 0:
        if arr1[i] < arr2[j]:
            i += 1
        else:
            j += 1
        k -= 1

    # If k is greater than the combined length of both arrays, return the last element of the longer array
    if k > 0:
        if i == len(arr1):
            return arr2[-1]
        else:
            return arr1[-1]

    # Return the kth element if both arrays have elements left
    return arr1[i] if k == 1 else arr2[j]

