def is_Diff(n):
    # Convert the number to a string to easily access each digit
    s = str(n)
    # Calculate the alternating sum of digits
    sum = 0
    for i in range(len(s)):
        if i % 2 == 0:
            sum += int(s[i])
        else:
            sum -= int(s[i])
    # Check if the alternating sum is divisible by 11
    return sum % 11 == 0

